         const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         if (!emailPattern.test(value.trim())) {
           return "Enter a valid email address.";
         }
         return "";
       }

       function validatePhone(value) {
         if (!value.trim()) {
           return "";
         }
         const phonePattern = /^\+?[0-9\s\-().]{7,20}$/;
         if (!phonePattern.test(value.trim())) {
           return "Enter a valid phone number using digits, spaces, or + - ( ).";
         }
         return "";
       }

       function validateField(fieldId, value) {
         switch (fieldId) {
           case "fullName":
             return validateFullName(value);
           case "email":
             return validateEmail(value);
           case "phone":
             return validatePhone(value);
           default:
             return "";
         }
       }

       function setFieldValue(fieldId, value) {
         state.values[fieldId] = value;
         state.errors[fieldId] = validateField(fieldId, value);
         state.status = "";
         renderApp();
       }

       function validateForm() {
         const nextErrors = {
           fullName: validateFullName(state.values.fullName),
           email: validateEmail(state.values.email),
           phone: validatePhone(state.values.phone),
         };

         state.errors = nextErrors;
         const hasError = Object.values(nextErrors).some(Boolean);

         if (!hasError) {
           state.status = "Thanks. Your support request is ready to send.";
         } else {
           state.status = "";
         }

         return !hasError;
       }

       function FormField(field) {
         const error = state.errors[field.id];
         const helperId = field.helperText ? `${field.id}-helper` : "";
         const errorId = `${field.id}-error`;
         const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

         return `
           <div class="form-field ${error ? "has-error" : ""}">
             <label for="${field.id}">
               ${field.label}${field.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
             </label>
             <input
               id="${field.id}"
               name="${field.id}"
               type="${field.type}"
               placeholder="${field.placeholder}"
               value="${escapeAttribute(state.values[field.id])}"
               ${field.required ? "required" : ""}
               aria-required="${field.required ? "true" : "false"}"
               aria-invalid="${error ? "true" : "false"}"
               ${describedBy ? `aria-describedby="${describedBy}"` : ""}
             />
             ${field.helperText ? `<div class="field-helper" id="${helperId}">${field.helperText}</div>` : ""}
             <div class="field-error" id="${errorId}" aria-live="polite">${error}</div>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="support-form-panel" aria-labelledby="contact-form-title">
             <div class="form-stack">
               <h2 id="contact-form-title">Contact support</h2>
               <p>Tell us a bit about yourself and we will direct your request to the right team.</p>
               <form id="support-form" novalidate>
                 ${fields.map(FormField).join("")}
                 <button class="submit-button" type="submit">Submit request</button>
                 <div class="status-message" aria-live="polite">${state.status}</div>
               </form>
             </div>
           </section>
         `;
       }

       function SupportHighlights() {
         return `
           <section class="support-copy" aria-labelledby="support-page-title">
             <div class="eyebrow">Support team</div>
             <h1 id="support-page-title">Get product help from a real person.</h1>
             <p class="lead">
               Reach out for onboarding guidance, billing help, or technical support. We keep the form short so you can get back to work faster.
             </p>
             <ul class="feature-list">
               <li><strong>Fast routing</strong>Your request lands with the team best equipped to help.</li>
               <li><strong>Clear updates</strong>We follow up with progress and next steps by email.</li>
               <li><strong>Flexible contact</strong>Add a phone number if you would like a callback.</li>
             </ul>
           </section>
         `;
       }

       function SupportPage() {
         return `
           <main class="page-shell">
             <div class="support-card">
               ${SupportHighlights()}
               ${ContactForm()}
             </div>
           </main>
         `;
       }

       function App() {
         return SupportPage();
       }

       function escapeAttribute(value) {
         return value
           .replace(/&/g, "&amp;")
           .replace(/"/g, "&quot;")
           .replace(/</g, "&lt;")
           .replace(/>/g, "&gt;");
       }

       function attachEventHandlers() {
         fields.forEach((field) => {
           const input = document.getElementById(field.id);
           input.addEventListener("input", (event) => {
             setFieldValue(field.id, event.target.value);
           });
           input.addEventListener("blur", (event) => {
             state.errors[field.id] = validateField(field.id, event.target.value);
             renderApp();
           });
         });

         document.getElementById("support-form").addEventListener("submit", (event) => {
           event.preventDefault();
           const isValid = validateForm();
           renderApp();

           if (isValid) {
             document.getElementById("support-form").reset();
             state.values = { fullName: "", email: "", phone: "" };
             state.errors = { fullName: "", email: "", phone: "" };
             state.status = "Thanks. Your support request has been submitted.";
             renderApp();
           }
         });
       }

       function renderApp() {
         document.getElementById("app").innerHTML = App();
